<section id="revisionStoryThreshold" class="revision-story-panel"><div class="revision-story-heading"><div><h3>${esc(t.thresholdTitle)}</h3><p>${esc(t.thresholdIntro.replace('30',String(m.threshold.pair_count)))}</p></div><label>${esc(t.query)}<select data-story-control="endpoint"><option value="earliest"${m.threshold.endpoint==='earliest'?' selected':''}>${esc(t.earliest)}</option><option value="latest"${m.threshold.endpoint==='latest'?' selected':''}>${esc(t.latest)}</option></select></label></div><dl class="revision-threshold-counts">${delta(t.beforeCount,m.threshold.earliest_count+'/'+m.threshold.pair_count)}${delta(t.afterCount,m.threshold.latest_count+'/'+m.threshold.pair_count)}${delta(t.crossings,String(m.threshold.crossings.length))}</dl>${example}<div class="revision-query"><span>${esc(t.criteria)}</span><code>${esc(criterion)}</code><strong>${m.threshold.members.length} ${esc(t.selected)}</strong></div><details class="revision-story-members"><summary>${esc(t.members)} (${m.threshold.members.length})</summary><div class="table-scroll"><table><thead><tr><th>${esc(t.id)}</th><th>${esc(t.earliest)}</th><th>${esc(t.latest)}</th><th>${esc(t.type)}</th></tr></thead><tbody>${m.threshold.members.map(p=>`<tr><td>${esc(p.event_id)}</td><td>${num(p.earliest,1)}</td><td>${num(p.latest,1)}</td><td>mww</td></tr>`).join('')}</tbody></table></div></details><p class="revision-story-note">${esc(t.noteThreshold)}</p></section>
